WITH with_gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM web_events), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT id, session_id, event_type, page, new_group_flag, burst_id FROM sessionized ORDER BY event_type DESC, burst_id ASC
